      /* token colors adjusted for dark background */
    }
    body.dark-theme footer {
      background: #3c3c3c;
      color: #aaa;
    }
  </style>
</head>
<body>
  <header>
    <div><strong>Advanced Notepad</strong></div>
    <div class="controls">
      <button id="new-btn" title="New File">New</button>
      <button id="open-btn" title="Open File">Open</button>
      <button id="save-btn" title="Save File (Ctrl+S)">Save</button>
      <select id="language-select" title="Select Language">
        <option value="plaintext">Plain Text</option>
        <option value="javascript" selected>JavaScript</option>
        <option value="html">HTML</option>
        <option value="css">CSS</option>
      </select>
      <button id="find-btn" title="Find/Replace">Find/Replace</button>
      <button id="theme-btn" title="Toggle Dark/Light">Toggle Theme</button>
    </div>
  </header>

  <!-- Find/Replace Panel -->
  <div id="find-panel">
    <input type="text" id="find-input" placeholder="Find">
    <input type="text" id="replace-input" placeholder="Replace">
    <button id="find-next-btn">Find Next</button>
    <button id="replace-btn">Replace</button>
    <button id="replace-all-btn">Replace All</button>
    <button id="close-find-btn">Close</button>
  </div>

  <div id="editor-container">
    <div id="line-numbers">1</div>
    <div id="editor-wrapper">
      <pre id="highlighting"></pre>
      <textarea id="editor" spellcheck="false" autocapitalize="off"></textarea>
    </div>
  </div>

  <footer id="status">Lines: 1 | Characters: 0</footer>

  <!-- Hidden file input for open -->
  <input type="file" id="file-input" style="display: none;">

  <script>
    /********* VARIABLES & INITIALIZATION **********/
    const editor = document.getElementById('editor');
    const highlighting = document.getElementById('highlighting');
    const lineNumbers = document.getElementById('line-numbers');
    const statusBar = document.getElementById('status');
    const languageSelect = document.getElementById('language-select');

    // For find/replace
    const findPanel = document.getElementById('find-panel');
    const findInput = document.getElementById('find-input');
    const replaceInput = document.getElementById('replace-input');
    let currentFindIndex = 0;

    // Load autosaved content if available
    if(localStorage.getItem('advancedNotepadContent')) {
      editor.value = localStorage.getItem('advancedNotepadContent');
    }
    updateEditor();

    /********* EVENT LISTENERS **********/

    // Update highlighting and line numbers on input
    editor.addEventListener('input', () => {
      updateEditor();
      autoSave();
    });

    // Sync scroll between textarea, pre, and line numbers
    editor.addEventListener('scroll', () => {
      highlighting.scrollTop = editor.scrollTop;
      lineNumbers.scrollTop = editor.scrollTop;
    });

    // Auto-indentation on Enter key
    editor.addEventListener('keydown', (e) => {
      if(e.key === 'Enter') {
        const start = editor.selectionStart;
        const value = editor.value;
        let indent = '';
        // Find the previous line
        const lineStart = value.lastIndexOf('\n', start - 1) + 1;
        const line = value.substring(lineStart, start);
        const match = line.match(/^\s+/);
        if(match) { indent = match[0]; }
        setTimeout(() => {
          const pos = editor.selectionStart;
          editor.value = editor.value.substring(0, pos) + indent + editor.value.substring(pos);
          editor.selectionStart = editor.selectionEnd = pos + indent.length;
          updateEditor();
        }, 0);
      }
      // Save Shortcut Ctrl+S
      if((e.ctrlKey || e.metaKey) && e.key === 's') {
        e.preventDefault();
        saveFile();
      }
    });

    // Toolbar buttons
    document.getElementById('new-btn').addEventListener('click', () => {
      if(confirm("Start a new file? Unsaved changes will be lost.")) {
        editor.value = "";
        updateEditor();
      }
    });

    document.getElementById('open-btn').addEventListener('click', () => {
      document.getElementById('file-input').click();
    });

    document.getElementById('save-btn').addEventListener('click', () => {
      saveFile();
    });

    document.getElementById('theme-btn').addEventListener('click', () => {
      document.body.classList.toggle('dark-theme');
    });

    languageSelect.addEventListener('change', () => {
      updateEditor();
    });

    // File Open handler
    document.getElementById('file-input').addEventListener('change', (e) => {
      const file = e.target.files[0];
      if(file) {
        const reader = new FileReader();
        reader.onload = function(evt) {
          editor.value = evt.target.result;
          updateEditor();
        };
        reader.readAsText(file);
      }
    });

    // Find/replace panel
    document.getElementById('find-btn').addEventListener('click', () => {
      findPanel.style.display = 'block';
      findInput.focus();
    });
    document.getElementById('close-find-btn').addEventListener('click', () => {
      findPanel.style.display = 'none';
    });
    document.getElementById('find-next-btn').addEventListener('click', findNext);
    document.getElementById('replace-btn').addEventListener('click', doReplace);
    document.getElementById('replace-all-btn').addEventListener('click', doReplaceAll);

    /********* FUNCTIONS **********/

    function updateEditor() {
      const code = editor.value;
      updateLineNumbers(code);
      updateStatus(code);
      const lang = languageSelect.value;
      const highlightedCode = syntaxHighlight(code, lang);
      highlighting.innerHTML = highlightedCode;
    }

    function updateLineNumbers(text) {
      const lines = text.split('\n').length;
      let lineHtml = '';
      for(let i=1;i<=lines;i++){
        lineHtml += i + '<br>';
      }
      lineNumbers.innerHTML = lineHtml;
    }

    function updateStatus(text) {
      const lines = text.split('\n').length;
      const chars = text.length;
      statusBar.textContent = `Lines: ${lines} | Characters: ${chars}`;
    }

    // Basic syntax highlighter
    function syntaxHighlight(text, lang) {
      // Escape HTML
      text = text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

      if(lang === 'plaintext'){
        return text;
      }
      else if(lang === 'javascript'){
        // Comments: //... and /* ... */
        text = text.replace(/(\/\*[\s\S]*?\*\/)|(\/\/.*$)/gm, match => '<span class="token comment">'+match+'</span>');
        // Strings: "..." or '...'
        text = text.replace(/("([^"\\]|\\.)*")|('([^'\\]|\\.)*')/g, match => '<span class="token string">'+match+'</span>');
        // Keywords
        const keywords = ["break", "case", "catch", "class", "const", "continue", "debugger", "default", "delete", "do", "else", "export", "extends", 
                          "finally", "for", "function", "if", "import", "in", "instanceof", "let", "new", "return", "super", "switch", "this", 
                          "throw", "try", "typeof", "var", "while", "with", "yield"];
        const kwRegex = new RegExp('\\b('+keywords.join('|')+')\\b', 'g');
        text = text.replace(kwRegex, '<span class="token keyword">$1</span>');
        // Numbers
        text = text.replace(/\b(\d+(\.\d+)?)\b/g, '<span class="token number">$1</span>');
      }
      else if(lang === 'html'){
        // Simple tag highlighting: tags, attributes and attribute values
        text = text.replace(/(&lt;!--[\s\S]*?--&gt;)/g, '<span class="token comment">$1</span>');
        text = text.replace(/(&lt;\/?[a-zA-Z]+)([^&]*?)(&gt;)/g, function(match, p1, p2, p3) {
          // Attributes within a tag:
          p2 = p2.replace(/([a-zA-Z-:]+)(=)("[^"]*"|'[^']*')/g, '<span class="token attr">$1</span>$2<span class="token attr-value">$3</span>');
          return '<span class="token tag">'+p1+'</span>' + p2 + '<span class="token tag">'+p3+'</span>';
        });
      }
      else if(lang === 'css'){
        // Comments
        text = text.replace(/(\/\*[\s\S]*?\*\/)/g, '<span class="token comment">$1</span>');
        // Selectors and property names (very basic)
        text = text.replace(/([.#]?[a-zA-Z0-9_-]+)(\s*\{)/g, '<span class="token keyword">$1</span>$2');
        // Strings
        text = text.replace(/("([^"\\]|\\.)*")|('([^'\\]|\\.)*')/g, match => '<span class="token string">'+match+'</span>');
        // Numbers
        text = text.replace(/\b(\d+(\.\d+)?)(px|em|rem|%)?\b/g, '<span class="token number">$1</span>');
      }

      return text;
    }

    function autoSave() {
      localStorage.setItem('advancedNotepadContent', editor.value);
    }

    function saveFile() {
      const blob = new Blob([editor.value], {type: "text/plain;charset=utf-8"});
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = "note.txt";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(url);
    }

    /********* FIND/REPLACE FUNCTIONS **********/
    function findNext() {
      const searchText = findInput.value;
      if(!searchText) return;
      const content = editor.value;
      currentFindIndex = content.indexOf(searchText, editor.selectionEnd);
      if(currentFindIndex === -1) {
        alert("No further matches.");
        return;
      }
      editor.focus();
      editor.selectionStart = currentFindIndex;
      editor.selectionEnd = currentFindIndex + searchText.length;
    }

    function doReplace() {
      const searchText = findInput.value;
      const replaceText = replaceInput.value;
      if(!searchText) return;
      const selStart = editor.selectionStart;
      const selEnd = editor.selectionEnd;
      if(editor.value.substring(selStart, selEnd) === searchText) {
        // Replace the current selection:
        const before = editor.value.substring(0, selStart);
        const after = editor.value.substring(selEnd);
        editor.value = before + replaceText + after;
        editor.selectionStart = selStart;
        editor.selectionEnd = selStart + replaceText.length;
        updateEditor();
      }
      findNext();
    }

    function doReplaceAll() {
      const searchText = findInput.value;
      const replaceText = replaceInput.value;
      if(!searchText) return;
      const regex = new RegExp(searchText, "g");
      editor.value = editor.value.replace(regex, replaceText);
      updateEditor();
    }

    /********* AUTO SAVE EVERY 3 SECONDS **********/
    setInterval(autoSave, 3000);

  </script>
</body>
</html>
────────────────────────────

How It Works:
1. The header holds buttons for New, Open (which uses a hidden file input), Save (also bound to Ctrl+S), a language selector that determines the syntax‐highlighting mode, and buttons for toggling the find/replace panel and light/dark theme.
2. The editor is created by layering a transparent textarea (for user input) over a pre element that shows HTML–formatted (highlighted) code. The line numbers are rendered in a fixed-width adjacent column.
3. The syntaxHighlight() function applies simple regular-expression replacements to “wrap” keywords, strings, comments, numbers, or (for HTML/CSS) tags, attributes, etc.
4. The find/replace panel lets you search through the text and replace either the current match or all occurrences.
5. Auto–save is performed (both immediately on input and every 3 seconds) to localStorage so that you don’t lose your work.

This single-file app can be further modified or enriched, but it already packs many cool features into one self-contained HTML file. Enjoy experimenting and extending it!

