            word-wrap: break-word;
            border: none;
            outline: none;
            background-color: var(--bg-color);
            color: var(--text-color);
            overflow-y: auto;
        }

        #line-numbers .line-number {
            display: block;
        }

        .keyword {
            color: var(--keyword-color);
        }

        .string {
            color: var(--string-color);
        }

        .comment {
            color: var(--comment-color);
        }

