            margin-right: 20px;
        }

        header {
            padding: 10px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            background-color: var(--bg-color);
            border-bottom: 1px solid #ccc;
        }

        button {
            padding: 8px 12px;
            font-size: 14px;
            cursor: pointer;
            background-color: #f0f0f0;
            border: 1px solid #ccc;
            border-radius: 4px;
        }

        button:hover {
            background-color: #e0e0e0;
        }
    </style>
</head>
<body>
    <header>
        <button onclick="save()">Save</button>
        <button onclick="load()">Load</button>
        <button onclick="toggleTheme()">Toggle Theme</button>
    </header>
    <div id="editor-container">
        <div id="line-numbers"></div>
        <div id="editor" contenteditable="true" spellcheck="false"></div>
    </div>
    <div id="status-bar">
        <span id="line-col">Ln 1, Col 1</span>
        <span id="word-count">0 words</span>
    </div>

    <script>
        const editor = document.getElementById('editor');
        const lineNumbers = document.getElementById('line-numbers');

        // Save selection for contenteditable
        function saveSelection(node) {
            if (window.getSelection) {
                const sel = window.getSelection();
                if (sel.rangeCount) {
                    return {
                        range: sel.getRangeAt(0),
                        scrollTop: node.scrollTop
                    };
                }
            }
            return null;
        }

        function restoreSelection(node, sel) {
            if (sel) {
                const s = window.getSelection();
                s.removeAllRanges();
                s.addRange(sel.range);
                node.scrollTop = sel.scrollTop;
            }
        }

        // Highlighting functions
        function processText(text) {
            let lines = text.split('\n');
            let result = '';
            lines.forEach(line => {
                // Strings
                line = line.replace(/(["'])(?:\\.|[^\\])*?\1/g, (match) => `<span class='string'>${match}</span>`);
                // Comments
                line = line.replace(/\/\/.*/g, (match) => `<span class='comment'>${match}</span>`);
                // Keywords
                const keywords = ['function', 'const', 'let', 'var', 'if', 'else', 'while', 'for', 'return'];
                keywords.forEach(kw => {
                    const regex = new RegExp(`\\b${kw}\\b`, 'g');
                    line = line.replace(regex, (match) => `<span class='keyword'>${match}</span>`);
                });
                result += line + '\n';
            });
            return result;
        }

        function highlightCode() {
            const savedSel = saveSelection(editor);

            const text = editor.textContent;
            const highlightedHTML = processText(text);

            editor.innerHTML = highlightedHTML;

            restoreSelection(editor, savedSel);
        }

        // Debounce function
        function debounce(func, delay) {
            let timer;
            return (...args) => {
                clearTimeout(timer);
                timer = setTimeout(() => func.apply(this, args), delay);
            };
        }

        // Line numbers
        function updateLineNumbers() {
            const text = editor.textContent;
            const lines = text.split('\n');
            let html = '';
            lines.forEach((_, index) => {
                html += `<span class="line-number">${index + 1}</span>\n`;
            });
            lineNumbers.innerHTML = html;
            lineNumbers.scrollTop = editor.scrollTop;
        }

        // Status bar
        function getCursorPosition() {
            const sel = window.getSelection();
            if (!sel.rangeCount) return { line: 1, column: 1 };
            const range = sel.getRangeAt(0).cloneRange();
            range.selectNodeContents(editor);
            range.setEnd(sel.getRangeAt(0).startContainer, sel.getRangeAt(0).startOffset);
            const text = range.toString();
            const lines = text.split('\n');
            const line = lines.length;
            const column = lines[lines.length - 1].length + 1;
            return { line, column };
        }

        function updateStatus() {
            const pos = getCursorPosition();
            document.getElementById('line-col').textContent = `Ln ${pos.line}, Col ${pos.column}`;

            const text = editor.textContent;
            const words = text.match(/\S+/g) || [];
            document.getElementById('word-count').textContent = `${words.length} words`;
        }

        // Auto-indent
        function handleEnterKey(e) {
            if (e.key === 'Enter') {
                e.preventDefault();
                const sel = window.getSelection();
                const range = sel.getRangeAt(0);
                const startOffset = range.startOffset;
                const text = editor.textContent;
                const lineText = text.substring(0, startOffset).split('\n').pop() || '';
                const indent = lineText.match(/^(\s*)/)[1];
                const newLine = '\n' + indent;
                document.execCommand('insertText', false, newLine);

                updateLineNumbers();
                updateStatus();
                highlightCode();
            }
        }

        // Event listeners
        const debouncedHighlight = debounce(highlightCode, 200);
        editor.addEventListener('input', () => {
            updateLineNumbers();
            updateStatus();
            debouncedHighlight();
        });

        editor.addEventListener('keydown', handleEnterKey);

        // Save/Load
        function save() {
            localStorage.setItem('code', editor.textContent);
            alert('Saved!');
        }

        function load() {
            const stored = localStorage.getItem('code');
            if (stored) {
                editor.textContent = stored;
                updateLineNumbers();
                updateStatus();
                highlightCode();
            }
        }

        // Theme toggle
        function toggleTheme() {
            const root = document.documentElement;
            if (root.style.getPropertyValue('--bg-color') === '#ffffff') {
                root.style.setProperty('--bg-color', '#2b2b2b');
                root.style.setProperty('--text-color', '#ffffff');
                root.style.setProperty('--keyword-color', '#ff00ff');
                root.style.setProperty('--string-color', '#00ff00');
                root.style.setProperty('--comment-color', '#808080');
            } else {
                root.style.setProperty('--bg-color', '#ffffff');
                root.style.setProperty('--text-color', '#000000');
                root.style.setProperty('--keyword-color', '#ff0000');
                root.style.setProperty('--string-color', '#008000');
                root.style.setProperty('--comment-color', '#808080');
            }
        }

        // Initialize
        updateLineNumbers();
        updateStatus();
    </script>
</body>
</html>
```

### Features included:
1. **Syntax Highlighting**: Basic highlighting for JavaScript keywords, strings, and comments
2. **Line Numbers**: Dynamically updated line numbers
3. **Auto-Indent**: Automatically matches indentation when pressing Enter
4. **Save/Load**: Persistent storage using localStorage
5. **Theme Switching**: Toggle between light and dark themes
6. **Status Bar**: Shows current line/column position and word count
7. **Word Wrap**: Long lines automatically wrap
8. **Debounced Rendering**: Prevents excessive re-rendering for smooth typing
9. **Cross-browser Support**: Uses standard DOM methods

### How to use:
1. Start typing in the editor area
2. Use the buttons to save/load content
3. Toggle theme with the "Toggle Theme" button
4. Status bar shows current position and word count
5. Press Enter to auto-indent new lines

This implementation provides a solid foundation with many useful features while keeping everything in a single HTML file. The syntax highlighting is basic but functional, and you could extend it with more complex regex patterns for better language support if needed.

