const startY = position.y;
const startZ = position.z;

const baseSize = 15; // Base dimension (15x15)
const levels = Math.floor(baseSize / 2) + 1; // Total levels (height)

for (let level = 0; level < levels; level++) {
    const currentSideLength = baseSize - (2 * level); // Decrease size by 2 each level
    const halfSide = Math.floor(currentSideLength / 2);

    // Define the current layer's boundaries (centered)
    const xMin = startX - halfSide;
    const xMax = startX + halfSide;
    const zMin = startZ - halfSide;
    const zMax = startZ + halfSide;
    const y = startY + level; // Height per layer

    // Place blocks for the current layer's square
    for (let x = xMin; x <= xMax; x++) {
        for (let z = zMin; z <= zMax; z++) {
            await skills.placeBlock(bot, 'sandstone', x, y, z);
        }
    }
}
```

