using UnityEngine;

public class moveCard : MonoBehaviour
{
    public storage Storage;
    public float speed = 20f;

    // Floating point variables for time and journey data
    private float startTime;
    private float journeyLength;

    // Instead of a Transform "marker", store the starting position here.
    private Vector3 startPos;
    private Vector3 endPos;

    public int dir = 1;

    void Awake() 
    {
        if (gameObject.name == "reference") 
        {
            Storage.movePos = transform.position;
        }
    }

    public void moveToCenter() 
    {
        // Capture the starting position now:
        startPos = transform.position;
        startTime = Time.time;

        // Compute the target/ending position only once
        endPos = new Vector3(Storage.movePos.x * dir, Storage.movePos.y, Storage.movePos.z);
        journeyLength = Vector3.Distance(startPos, endPos);

        // Start the movement coroutine.
        StartCoroutine(Move());
        // Optionally: if you want to force-stop the coroutine later,
        // it’s better to store the Coroutine handle.
        Invoke("StopAnimation", 2f);
    }

    IEnumerator Move() 
    {
        while (true) 
        {
            // Calculate the distance traveled so far and the percentage of journey completed    
            float distance = (Time.time - startTime) * speed;
            float journeyAmount = distance / journeyLength;

            // Clamp journeyAmount (if necessary) so it doesn't exceed 1
            if(journeyAmount < 1f)
            {
