                transform.rotation = Quaternion.Lerp(Quaternion.Euler(transform.rotation.eulerAngles), Quaternion.Euler(Storage.rot), journeyAmount);
                yield return null;
            }
            else 
            {
                // Ensure we reach the end exactly.
                transform.position = endPos;
                transform.rotation = Quaternion.Euler(Storage.rot);
                yield break;
            }
        }
    } 

    private void StopAnimation() 
    {
        Debug.Log("Coroutine ended");
        // If you want to stop the coroutine from elsewhere,
        // consider keeping a reference to the started Coroutine.
    }
}
-------------------------------------------------

