    private Transform startMarker;
    private float distance; // Initialize to 0 by default
    public int dir = 1;
    private Vector3 endPos;
    private Coroutine currentMove; // Store the coroutine reference

    void Awake() {
        if (gameObject.name == "reference") {
            Storage.movePos = transform.position;
        }
    }

    public void moveToCenter() {
        startMarker = this.transform;
        startTime = Time.time;

        endPos = new Vector3(Storage.movePos.x * dir, Storage.movePos.y, Storage.movePos.z);
        journeyLength = Vector3.Distance(transform.position, endPos);
        distance = 0f; // Reset distance before starting new movement

        // Start the coroutine and store its reference
        currentMove = StartCoroutine(move());
        // Removed Invoke("stopAnimation", 2f) since it's unnecessary
    }

    IEnumerator move() {
        Debug.Log(endPos);
        while (true) {
            // Correct order: calculate distance first, then journeyAmount
            distance = (Time.time - startTime) * speed;
            float journeyAmount = distance / journeyLength;

            if (journeyAmount < 1f) {
                transform.position = Vector3.Lerp(startMarker.position, endPos, journeyAmount);
                transform.rotation = Quaternion.Lerp(startMarker.rotation, Quaternion.Euler(Storage.rot), journeyAmount);
            } else {
                break; // Exit loop when done
            }
            yield return null;
        }
        // Optional: Reset startMarker or other variables here if needed
    }

    // Removed stopAnimation method since it's no longer needed
}
```

**Key Fixes:**

1. **Calculation Order in Coroutine:**
   - Fixed the order by calculating `distance` before `journeyAmount` to ensure the current time is used.

2. **Coroutine Management:**
   - Added `currentMove` to store the coroutine reference.
   - Started the coroutine using `currentMove = StartCoroutine(move());` for proper control.

3. **Removed Unnecessary Stop:**
   - Removed `Invoke("stopAnimation", 2f)` and the `stopAnimation` method entirely. The coroutine now exits naturally when the movement completes.

**Why These Fixes Work:**

- **Calculation Order:** By recalculating `distance` (based on current time and speed) before computing `journeyAmount`, the interpolation now uses the correct progress value each frame.

- **Coroutine Control:** Properly storing and managing the coroutine ensures you can stop it if needed (though it's not required here since the loop exits on its own).

- **Movement Duration:** Removing the forced `Invoke` call allows the movement to complete naturally, ensuring the object reaches `endPos`.

**Additional Notes:**

- **Speed Consideration:** The movement duration depends on `speed` and `journeyLength`. To make the movement take exactly `t` seconds, set `speed = journeyLength / t`.

- **Rotation:** Ensure `Storage.rot` holds the correct target rotation values.

- **Edge Cases:** If `dir` changes dynamically, ensure `endPos` is recalculated if needed. However, in the current setup, it's computed once when `moveToCenter()` is called.

This should resolve the issue where the object didn't reach `endPos` due to incorrect calculations and premature stopping.
